import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Check, X, ArrowLeft } from 'lucide-react';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const formatDate = (dateString) => {
    const options = { year: 'numeric', month: '2-digit', day: '2-digit' };
    return new Date(dateString).toLocaleDateString('es-ES', options);
};

const AdminVacations = () => {
    const [requests, setRequests] = useState([]);
    const [pendingCount, setPendingCount] = useState(0);
    const [comments, setComments] = useState({});
    const [error, setError] = useState(null);
    const navigate = useNavigate();

    const fetchVacationRequests = async () => {
        try {
            const response = await fetch(`${API_BASE_URL}/admin/vacation-requests`);
            const data = await response.json();

            if (!Array.isArray(data)) {
                setError('Formato de respuesta inesperado');
                setRequests([]);
                return;
            }

            setRequests(data);
            const uniquePendingGroups = new Set(
                data.filter(req => req.status === 'pending')
                    .map(req => req.request_group_id)
            );
            setPendingCount(uniquePendingGroups.size);
            setError(null);
        } catch (error) {
            console.error('Error fetching vacation requests:', error);
            setError('Error al cargar las solicitudes');
            setRequests([]);
        }
    };

    useEffect(() => {
        fetchVacationRequests();
    }, []);

    const handleStatusChange = async (requestGroupId, status) => {
        try {
            const comment = comments[requestGroupId] || '';

            const response = await fetch(`${API_BASE_URL}/admin/vacation-request-group/${requestGroupId}`, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status, comments: comment }),
            });

            if (response.ok) {
                fetchVacationRequests();
                alert(`Solicitud ${status === 'approved' ? 'aprobada' : 'rechazada'} correctamente`);
            } else {
                setError('Error al actualizar la solicitud');
            }
        } catch (error) {
            console.error('Error updating request:', error);
            setError('Error al procesar la solicitud');
        }
    };

    const groupedRequests = useMemo(() => {
        const groups = {};
        requests.forEach(req => {
            if (!groups[req.request_group_id]) {
                groups[req.request_group_id] = {
                    id: req.request_group_id,
                    user_id: req.user_id,
                    name: req.user_name,
                    dates: [],
                    status: req.status,
                    comments: req.comments,
                    request_group_id: req.request_group_id
                };
            }
            groups[req.request_group_id].dates.push(req.vacation_date);
        });
        return groups;
    }, [requests]);

    return (
        <div className="min-h-screen bg-gray-50 p-6">
            <div className="flex items-center mb-6 gap-4">
                <button
                    onClick={() => navigate('/admin')}
                    className="w-10 h-10 rounded-lg bg-red-600 text-white shadow hover:bg-red-700 transition flex-shrink-0 flex items-center justify-center"
                    aria-label="Volver al panel de administración"
                >
                    <ArrowLeft size={20} />
                </button>
                <h1 className="text-3xl font-bold text-gray-800">Gestión de Vacaciones</h1>
                {pendingCount > 0 && (
                    <span className="bg-red-500 text-white rounded-full px-2 py-1 text-xs">
                        {pendingCount} pendientes
                    </span>
                )}
            </div>

            {error && (
                <div className="mb-4 p-3 bg-red-100 text-red-700 rounded">
                    {error}
                </div>
            )}

            <div className="bg-white shadow-lg rounded-lg overflow-hidden">
                <div className="bg-requena-red p-4">
                    <h2 className="text-xl font-semibold text-white">Solicitudes de Vacaciones</h2>
                </div>

                {requests.length === 0 ? (
                    <div className="p-6 text-center text-gray-500">
                        {error ? 'Error al cargar solicitudes' : 'No hay solicitudes de vacaciones para revisar.'}
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full">
                            <thead className="bg-red-50">
                            <tr>
                                <th className="p-3 text-left">Empleado</th>
                                <th className="p-3 text-left">Fechas</th>
                                <th className="p-3 text-left">Estado</th>
                                <th className="p-3 text-left">Comentarios</th>
                                <th className="p-3 text-left">Acciones</th>
                            </tr>
                            </thead>
                            <tbody>
                            {Object.values(groupedRequests).map(group => {
                                const sortedDates = [...group.dates].sort();
                                const from = sortedDates[0];
                                const to = sortedDates[sortedDates.length - 1];
                                const dateRange = from === to
                                    ? formatDate(from)
                                    : `${formatDate(from)} al ${formatDate(to)}`;

                                return (
                                    <tr key={group.id} className="border-b hover:bg-gray-50">
                                        <td className="p-3">{group.name}</td>
                                        <td className="p-3">{dateRange}</td>
                                        <td className="p-3">
                                                <span className={`px-2 py-1 rounded-full text-xs ${
                                                    group.status === 'approved' ? 'bg-green-100 text-green-800' :
                                                        group.status === 'rejected' ? 'bg-red-100 text-red-800' :
                                                            'bg-yellow-100 text-yellow-800'
                                                }`}>
                                                    {group.status === 'approved' ? 'Aprobado' :
                                                        group.status === 'rejected' ? 'Rechazado' : 'Pendiente'}
                                                </span>
                                        </td>
                                        <td className="p-3">
                                            {group.status !== 'pending' ? (
                                                <div className="text-sm text-gray-600">
                                                    {group.comments || 'Sin comentarios'}
                                                </div>
                                            ) : (
                                                <textarea
                                                    placeholder="Comentarios (opcional)"
                                                    className="w-full p-2 border rounded text-sm"
                                                    onChange={(e) => setComments({
                                                        ...comments,
                                                        [group.id]: e.target.value
                                                    })}
                                                    aria-label="Comentarios sobre la solicitud"
                                                />
                                            )}
                                        </td>
                                        <td className="p-3">
                                            {group.status === 'pending' && (
                                                <div className="flex gap-2">
                                                    <button
                                                        onClick={() => handleStatusChange(group.id, 'approved')}
                                                        className="bg-green-500 text-white p-2 rounded hover:bg-green-600 transition"
                                                        title="Aprobar"
                                                        aria-label="Aprobar solicitud"
                                                    >
                                                        <Check size={16} />
                                                    </button>
                                                    <button
                                                        onClick={() => handleStatusChange(group.id, 'rejected')}
                                                        className="bg-red-500 text-white p-2 rounded hover:bg-red-600 transition"
                                                        title="Rechazar"
                                                        aria-label="Rechazar solicitud"
                                                    >
                                                        <X size={16} />
                                                    </button>
                                                </div>
                                            )}
                                        </td>
                                    </tr>
                                );
                            })}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
        </div>
    );
};

export default AdminVacations;
